set -eu
python - <<'PY' "$(inputs.snps.path)" > build_diagnostic.tsv
import sys, urllib.request, urllib.parse, json, time
import pandas as pd
snps=pd.read_csv(sys.argv[1], sep='\t')
print('\t'.join(['genome','coord_model','checked','matches','mismatches','errors','match_rate','examples']))
for genome in ['hg19','hg38']:
  for model in ['one_based','zero_based_start_as_given']:
    checked=matches=errors=0; examples=[]
    for _,r in snps.iterrows():
      chrom=str(r['chr']); pos=int(r['start']); ref=str(r['ref']).upper()
      if model=='one_based':
        s=pos-1; e=s+len(ref)
      else:
        s=pos; e=s+len(ref)
      url='https://api.genome.ucsc.edu/getData/sequence?' + urllib.parse.urlencode({'genome':genome,'chrom':chrom,'start':s,'end':e})
      try:
        with urllib.request.urlopen(url, timeout=20) as fh:
          data=json.loads(fh.read().decode())
        seq=data.get('dna','').upper()
        if not seq:
          raise RuntimeError(str(data)[:120])
        checked+=1
        if seq==ref:
          matches+=1
        elif len(examples)<5:
          examples.append(f'{chrom}:{pos}:{ref}>{seq}')
      except Exception as exc:
        errors+=1
        if len(examples)<5:
          examples.append(f'{chrom}:{pos}:ERR:{type(exc).__name__}')
    mismatches=checked-matches
    rate=(matches/checked) if checked else 0
    print('\t'.join(map(str,[genome,model,checked,matches,mismatches,errors,f'{rate:.4f}', ';'.join(examples)])))
PY

